/** Left-leaning educational red-black insertion with invariant comments. */
public class RedBlackTreeEducational { static class Node{int key; boolean red=true; Node left,right; Node(int k){key=k;}} Node root; boolean isRed(Node n){return n!=null&&n.red;} Node rotateLeft(Node h){Node x=h.right;h.right=x.left;x.left=h;x.red=h.red;h.red=true;return x;} Node rotateRight(Node h){Node x=h.left;h.left=x.right;x.right=h;x.red=h.red;h.red=true;return x;} void flip(Node h){h.red=!h.red;h.left.red=!h.left.red;h.right.red=!h.right.red;} public void insert(int k){root=insert(root,k);root.red=false;} Node insert(Node h,int k){if(h==null)return new Node(k); if(k<h.key)h.left=insert(h.left,k); else if(k>h.key)h.right=insert(h.right,k); if(isRed(h.right)&&!isRed(h.left))h=rotateLeft(h); if(isRed(h.left)&&isRed(h.left.left))h=rotateRight(h); if(isRed(h.left)&&isRed(h.right))flip(h); return h;} int blackHeight(Node n){ if(n==null)return 1; int l=blackHeight(n.left), r=blackHeight(n.right); if(l!=r)throw new IllegalStateException("black-height mismatch"); if(isRed(n)&&(isRed(n.left)||isRed(n.right)))throw new IllegalStateException("red violation"); return l+(n.red?0:1);} public boolean check(){return root==null||(!root.red&&blackHeight(root)>0);} public static void main(String[] a){RedBlackTreeEducational t=new RedBlackTreeEducational(); for(int x:new int[]{10,20,30,15,5})t.insert(x); System.out.println("Red-black invariants valid: "+t.check());}}
